const { data, error } = await (supabase.from('inventory_movements' as never) as unknown as {
  insert: (v: unknown) => { select: () => { single: () => Promise<{ data: unknown; error: unknown }> } }
}).insert({
  studio_id: member.studio_id,
  item_id: id,
  qty_delta,
  qty_after,
  reason,
  notes: notes ?? null,
  performed_by: user.id,
}).select().single()

